import java.math.BigDecimal
import java.math.RoundingMode

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        if (id in balances) {
            throw IllegalArgumentException("Account with id '$id' already exists")
        }
        // Validate initial amount has at most 2 decimal places
        val validatedInitial = validateAmount(initial)
        balances[id] = validatedInitial
        log[id] = mutableListOf()
        if (validatedInitial != BigDecimal.ZERO) {
            log[id]?.add(validatedInitial)
        }
    }

    fun balance(id: String): BigDecimal {
        return balances[id] ?: throw NoSuchElementException("Account with id '$id' not found")
    }

    fun transfer(from: String, to: String, amount: BigDecimal) {
        // Validate amount
        val validatedAmount = validateAmount(amount)

        // Check if accounts exist
        if (from !in balances) throw NoSuchElementException("Account with id '$from' not found")
        if (to !in balances) throw NoSuchElementException("Account with id '$to' not found")

        // Check for positive amount
        if (validatedAmount <= BigDecimal.ZERO) {
            throw IllegalArgumentException("Amount must be positive")
        }

        // Check if transfer would overdraw
        val newFromBalance = balances[from]!! - validatedAmount
        if (newFromBalance < BigDecimal.ZERO) {
            throw IllegalStateException("Insufficient funds")
        }

        // Perform the transfer
        balances[from] = newFromBalance
        balances[to] = balances[to]!! + validatedAmount

        // Log the transactions
        log[from]?.add(-validatedAmount)
        log[to]?.add(validatedAmount)
    }

    fun history(id: String): List<BigDecimal> {
        return log[id] ?: throw NoSuchElementException("Account with id '$id' not found")
    }

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            require(n > 0) { "Number of parts must be positive" }

            // Validate total has at most 2 decimal places
            val validatedTotal = validateAmount(total)

            // Calculate base amount and remainder
            val base = validatedTotal.divide(BigDecimal(n), 2, RoundingMode.DOWN)
            val remainder = validatedTotal - base * BigDecimal(n)

            // Create list with larger parts first
            val result = mutableListOf<BigDecimal>()
            val remainderCents = remainder.multiply(BigDecimal(100)).toInt()

            // Add parts with extra cent first (larger parts first)
            for (i in 0 until remainderCents) {
                result.add(base + BigDecimal("0.01"))
            }

            // Add remaining parts
            for (i in remainderCents until n) {
                result.add(base)
            }

            return result
        }

        private fun validateAmount(amount: BigDecimal): BigDecimal {
            // Check if amount has more than 2 decimal places
            val scaledAmount = amount.setScale(2, RoundingMode.DOWN)
            if (amount != scaledAmount) {
                throw IllegalArgumentException("Amount must have at most 2 decimal places")
            }

            // Check if amount is positive
            if (amount <= BigDecimal.ZERO) {
                throw IllegalArgumentException("Amount must be positive")
            }

            return amount
        }
    }
}
