import java.util.*

class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        require(capacity >= 1) { "Capacity must be at least 1, got $capacity" }
    }

    private data class Entry<K, V>(val key: K, var value: V, var prev: Entry<K, V>? = null, var next: Entry<K, V>? = null)

    private val head: Entry<K, V>? = null // least recently used
    private val tail: Entry<K, V>? = null // most recently used
    private val map = HashMap<K, Entry<K, V>>()
    private var size = 0

    init {
        // Initialize dummy head and tail nodes for easier doubly-linked list operations
        val dummyHead = Entry<K, V>(null as K, null as V)
        val dummyTail = Entry<K, V>(null as K, null as V)
        dummyHead.next = dummyTail
        dummyTail.prev = dummyHead
        // We'll use these dummy nodes as sentinels
        // But since we can't store them in the class fields directly due to nullability,
        // we'll use a different approach: maintain head and tail references that can be null
    }

    // Alternative implementation using a LinkedHashMap-like approach with a doubly-linked list
    private val dummyHead = Entry<K, V>(null as K, null as V)
    private val dummyTail = Entry<K, V>(null as K, null as V)

    init {
        dummyHead.next = dummyTail
        dummyTail.prev = dummyHead
    }

    private fun removeNode(node: Entry<K, V>) {
        node.prev?.next = node.next
        node.next?.prev = node.prev
        node.prev = null
        node.next = null
    }

    private fun addToTail(node: Entry<K, V>) {
        node.prev = dummyTail.prev
        node.next = dummyTail
        dummyTail.prev?.next = node
        dummyTail.prev = node
    }

    private fun moveToTail(node: Entry<K, V>) {
        removeNode(node)
        addToTail(node)
    }

    private fun evictLeastRecentlyUsed() {
        if (size > 0) {
            val lruNode = dummyHead.next!!
            removeNode(lruNode)
            map.remove(lruNode.key)
            onEvict(lruNode.key, lruNode.value)
            size--
        }
    }

    operator fun get(key: K): V? {
        val node = map[key]
        if (node == null) return null

        moveToTail(node)
        return node.value
    }

    operator fun set(key: K, value: V) {
        val existingNode = map[key]

        if (existingNode != null) {
            // Update existing entry
            existingNode.value = value
            moveToTail(existingNode)
        } else {
            // Create new entry
            val newNode = Entry(key, value)
            map[key] = newNode
            addToTail(newNode)
            size++

            // Evict if over capacity
            if (size > capacity) {
                evictLeastRecentlyUsed()
            }
        }
    }

    fun remove(key: K): V? {
        val node = map.remove(key)
        if (node != null) {
            removeNode(node)
            size--
            return node.value
        }
        return null
    }

    val size: Int
        get() = this.size

    fun keys(): List<K> {
        val result = mutableListOf<K>()
        var current = dummyHead.next
        while (current != dummyTail) {
            current?.key?.let { result.add(it) }
            current = current?.next
        }
        return result
    }

    operator fun contains(key: K): Boolean = map.containsKey(key)
}
