            // Create new entry
            val newNode = Entry(key, value)
            entries[key] = newNode
            addToTail(newNode)
            currentSize++

            // Evict if over capacity
            if (currentSize > capacity) {
                evictLeastRecentlyUsed()
            }
        }
    }

