fun toJson(value: Any?, indent: Int = 0): String {
    if (indent < 0) {
        throw IllegalArgumentException("Indent must be non-negative")
    }

    return serialize(value, indent, 0)
}

private fun serialize(value: Any?, indent: Int, level: Int): String {
    return when (value) {
        null -> "null"
        is Boolean -> value.toString()
        is String -> escapeString(value)
        is Int -> value.toString()
        is Long -> value.toString()
        is Float -> serializeDouble(value.toDouble(), indent, level)
        is Double -> serializeDouble(value, indent, level)
        is Map<*, *> -> serializeMap(value, indent, level)
        is List<*> -> serializeList(value, indent, level)
        is Array<*> -> serializeArray(value, indent, level)
        is Enum<*> -> escapeString(value.name)
        else -> throw IllegalArgumentException("Unsupported type: ${value::class.simpleName}")
    }
}

private fun serializeDouble(value: Double, indent: Int, level: Int): String {
    if (!value.isFinite()) {
        throw IllegalArgumentException("Non-finite double value: $value")
    }

    // Use Kotlin's toString() for doubles
    val str = value.toString()

    // For integer-like doubles (e.g., 2.0), we still use toString() which gives "2.0"
    // This matches the requirement: "a Double like 2.0 prints 2.0"
    return str
}

private fun serializeMap(map: Map<*, *>, indent: Int, level: Int): String {
    if (map.isEmpty()) {
        return "{}"
    }

    val sb = StringBuilder()
    val keys = map.keys.toList()

    if (indent == 0) {
        sb.append("{")
        for ((i, key) in keys.withIndex()) {
            if (i > 0) sb.append(",")
            if (key !is String) {
                throw IllegalArgumentException("Map key must be String, got ${key::class.simpleName}")
            }
            sb.append(escapeString(key))
            sb.append(":")
            sb.append(serialize(map[key], indent, level))
        }
        sb.append("}")
    } else {
        sb.append("{\n")
        val indentStr = " ".repeat(indent)
        val currentIndent = " ".repeat((level + 1) * indent)

        for ((i, key) in keys.withIndex()) {
            if (key !is String) {
                throw IllegalArgumentException("Map key must be String, got ${key::class.simpleName}")
            }
            sb.append(currentIndent)
            sb.append(escapeString(key))
            sb.append(": ")
            sb.append(serialize(map[key], indent, level + 1))
            if (i < keys.size - 1) {
                sb.append(",")
            }
            sb.append("\n")
        }
        sb.append(" ".repeat(level * indent))
        sb.append("}")
    }

    return sb.toString()
}

private fun serializeList(list: List<*>, indent: Int, level: Int): String {
    if (list.isEmpty()) {
        return "[]"
    }

    val sb = StringBuilder()

    if (indent == 0) {
        sb.append("[")
        for ((i, item) in list.withIndex()) {
            if (i > 0) sb.append(",")
            sb.append(serialize(item, indent, level))
        }
        sb.append("]")
    } else {
        sb.append("[\n")
        val indentStr = " ".repeat(indent)
        val currentIndent = " ".repeat((level + 1) * indent)

        for ((i, item) in list.withIndex()) {
            sb.append(currentIndent)
            sb.append(serialize(item, indent, level + 1))
            if (i < list.size - 1) {
                sb.append(",")
            }
            sb.append("\n")
        }
        sb.append(" ".repeat(level * indent))
        sb.append("]")
    }

    return sb.toString()
}

private fun serializeArray(array: Array<*>, indent: Int, level: Int): String {
    if (array.isEmpty()) {
        return "[]"
    }

    val sb = StringBuilder()

    if (indent == 0) {
        sb.append("[")
        for ((i, item) in array.withIndex()) {
            if (i > 0) sb.append(",")
            sb.append(serialize(item, indent, level))
        }
        sb.append("]")
    } else {
        sb.append("[\n")
        val indentStr = " ".repeat(indent)
        val currentIndent = " ".repeat((level + 1) * indent)

        for ((i, item) in array.withIndex()) {
            sb.append(currentIndent)
            sb.append(serialize(item, indent, level + 1))
            if (i < array.size - 1) {
                sb.append(",")
            }
            sb.append("\n")
        }
        sb.append(" ".repeat(level * indent))
        sb.append("]")
    }

    return sb.toString()
}

private fun escapeString(s: String): String {
    val sb = StringBuilder()
    sb.append('"')

    for (c in s) {
        when (c) {
            '"' -> sb.append("\\\"")
            '\\' -> sb.append("\\\\")
            '\b' -> sb.append("\\b")
            '\f' -> sb.append("\\f")
            '\n' -> sb.append("\\n")
            '\r' -> sb.append("\\r")
            '\t' -> sb.append("\\t")
            else -> {
                if (c.code < 0x20) {
                    // Control characters below 0x20: escape as \u00XX
                    sb.append("\\u00")
                    sb.append(String.format("%02x", c.code))
                } else {
                    sb.append(c)
                }
            }
        }
    }

    sb.append('"')
    return sb.toString()
}
