```kotlin
sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}

class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    var lastToken: Token? = null

    while (i < input.length) {
        // Skip whitespace
        if (input[i].isWhitespace()) {
            i++
            continue
        }

        val startPos = i

        // Try to match parentheses
        if (input[i] == '(') {
            tokens.add(Token.Paren(true, startPos))
            i++
            lastToken = tokens.last()
            continue
        }
        if (input[i] == ')') {
            tokens.add(Token.Paren(false, startPos))
            i++
            lastToken = tokens.last()
            continue
        }

        // Try to match operators (longest match first)
        val operatorCandidates = listOf("==", "!=", "<=", ">=", "&&", "||", ">", "<", "!")
        for (op in operatorCandidates) {
            if (input.startsWith(op, i)) {
                tokens.add(Token.Op(op, startPos))
                i += op.length
                lastToken = tokens.last()
                break
            }
        }
        if (tokens.lastOrNull() is Token.Op && tokens.last().pos == startPos) {
            continue
        }

        // Try to match identifiers
        if (input[i].isLetterOrDigit() || input[i] == '_') {
            val sb = StringBuilder()
            while (i < input.length && (input[i].isLetterOrDigit() || input[i] == '_' || input[i] == '.')) {
                sb.append(input[i])
                i++
            }
            tokens.add(Token.Ident(sb.toString(), startPos))
            lastToken = tokens.last()
            continue
        }

        // Try to match strings
        if (input[i] == '"' || input[i] == '\'') {
            val quote = input[i]
            i++ // skip opening quote
            val sb = StringBuilder()

            while (i < input.length) {
                if (input[i] == '\\' && i + 1 < input.length) {
                    i++ // skip backslash
                    when (input[i]) {
                        'n' -> sb.append('\n')
                        't' -> sb.append('\t')
                        'r' -> sb.append('\r')
                        else -> sb.append(input[i])
                    }
                    i++
                } else if (input[i] == quote) {
                    i++ // skip closing quote
                    tokens.add(Token.Str(sb.toString(), startPos))
                    lastToken = tokens.last()
                    break
                } else {
                    sb.append(input[i])
                    i++
                }
            }

            // If we didn't find the closing quote
            if (i >= input.length && input[i-1] != quote) {
                throw TokenizeException("Unterminated string", startPos)
            }
            continue
        }

        // Try to match numbers
        if (input[i].isDigit() || (input[i] == '-' && canStartWithMinus(lastToken))) {
            // Handle negative numbers
            if (input[i] == '-') {
                i++
                // Check if next char is digit or dot
                if (i >= input.length || (!input[i].isDigit() && input[i] != '.')) {
                    throw TokenizeException("Invalid character after '-'", startPos)
                }
            }

            val numStart = i
            var hasDot = false
            var hasDigitBeforeDot = false

            // Handle leading dot case (like .5)
            if (input[i] == '.') {
                if (i + 1 >= input.length || !input[i+1].isDigit()) {
                    throw TokenizeException("Invalid number", startPos)
                }
                i++
                hasDot = true
            } else {
                // Digits before dot
                while (i < input.length && input[i].isDigit()) {
                    hasDigitBeforeDot = true
                    i++
                }
                // Check for decimal point
                if (i < input.length && input[i] == '.') {
                    if (hasDot) {
                        throw TokenizeException("Invalid number", startPos)
                    }
                    i++
                    hasDot = true

                    // After dot, must have at least one digit
                    if (i >= input.length || !input[i].isDigit()) {
                        throw TokenizeException("Invalid number", startPos)
                    }
                }
            }

            // Digits after dot
            while (i < input.length && input[i].isDigit()) {
                i++
            }

            // Check for malformed number like "5." (no digits after dot)
            if (hasDot && i == numStart + 1 && input[numStart] == '.') {
                throw TokenizeException("Invalid number", startPos)
            }

            val numStr = input.substring(startPos, i)
            try {
                tokens.add(Token.Num(numStr.toDouble(), startPos))
                lastToken = tokens.last()
            } catch (e: NumberFormatException) {
                throw TokenizeException("Invalid number", startPos)
            }
            continue
        }

        // If we get here, we have an invalid character
        throw TokenizeException("Unexpected character '${input[i]}'", startPos)
    }

    return tokens
}

private fun canStartWithMinus(token: Token?): Boolean {
    return token == null || token is Token.Op || (token is Token.Paren && token.open)
}
