from typing import List, Set, Tuple

# Month and day name mappings
MONTH_NAMES = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
}

DAY_NAMES = {
    'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
}

def parse_field(field: str, min_val: int, max_val: int, name_map: dict = None) -> Set[int]:
    """Parse a cron field and return a set of valid values."""
    values = set()

    # Split by comma
    parts = field.split(',')

    for part in parts:
        part = part.strip()
        if not part:
            raise ValueError("Empty field part")

        # Check for step
        step = 1
        if '/' in part:
            base, step_str = part.split('/', 1)
            try:
                step = int(step_str)
                if step <= 0:
                    raise ValueError("Step must be positive")
            except ValueError:
                raise ValueError(f"Invalid step value: {step_str}")
        else:
            base = part

        # Parse base
        if base == '*':
            # All values in range
            for i in range(min_val, max_val + 1, step):
                values.add(i)
        elif '-' in base:
            # Range
            range_parts = base.split('-', 1)
            if len(range_parts) != 2:
                raise ValueError(f"Invalid range: {base}")

            start_str, end_str = range_parts
            start = parse_value(start_str, name_map)
            end = parse_value(end_str, name_map)

            if start > end:
                raise ValueError(f"Invalid range: {start} > {end}")

            for i in range(start, end + 1, step):
                values.add(i)
        else:
            # Single value
            val = parse_value(base, name_map)
            if step == 1:
                values.add(val)
            else:
                # For single value with step, it's just that value
                # But if it's not in the range, it's invalid
                if val < min_val or val > max_val:
                    raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")
                values.add(val)

    # Validate all values are in range
    for val in values:
        if val < min_val or val > max_val:
            raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")

    return values

def parse_value(value_str: str, name_map: dict = None) -> int:
    """Parse a single value, handling names if provided."""
    value_str = value_str.strip()

    # Try to parse as integer
    try:
        return int(value_str)
    except ValueError:
        pass

    # Try to parse as name
    if name_map:
        upper_val = value_str.upper()
        if upper_val in name_map:
            return name_map[upper_val]

    raise ValueError(f"Invalid value: {value_str}")

def is_leap_year(year: int) -> bool:
    """Check if a year is a leap year."""
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

def days_in_month(year: int, month: int) -> int:
    """Get the number of days in a month."""
    if month == 2:
        return 29 if is_leap_year(year) else 28
    elif month in [4, 6, 9, 11]:
        return 30
    else:
        return 31

def matches_cron(dt: datetime.datetime, minute_set: Set[int], hour_set: Set[int],
                 dom_set: Set[int], month_set: Set[int], dow_set: Set[int]) -> bool:
    """Check if a datetime matches the cron expression."""
    # Check month
    if dt.month not in month_set:
        return False

    # Check day
    # Vixie cron rule: if both dom and dow are restricted (not *), match if either matches
    # Otherwise, both must match

    dom_restricted = dom_set != set(range(1, 32))
    dow_restricted = dow_set != set(range(0, 7))

    dom_match = dt.day in dom_set
    dow_match = dt.weekday() + 1 if dt.weekday() < 6 else 0  # Convert Python weekday to cron weekday
    dow_match = dow_match in dow_set

    if dom_restricted and dow_restricted:
        # Either must match
        if not (dom_match or dow_match):
            return False
    else:
        # Both must match
        if not (dom_match and dow_match):
            return False

    # Check hour and minute
    if dt.hour not in hour_set:
        return False
    if dt.minute not in minute_set:
        return False

    return True

def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """Find the next fire time for a cron expression after the given datetime."""
    # Split into 5 fields
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    # Parse fields
    try:
        minute_set = parse_field(minute_field, 0, 59)
        hour_set = parse_field(hour_field, 0, 23)
        dom_set = parse_field(dom_field, 1, 31)
        month_set = parse_field(month_field, 1, 12, MONTH_NAMES)
        dow_set = parse_field(dow_field, 0, 7, DAY_NAMES)
        # Normalize Sunday (7 -> 0)
        if 7 in dow_set:
            dow_set.add(0)
            dow_set.discard(7)
    except ValueError as e:
        raise ValueError(f"Invalid cron expression: {e}")

    # Start from the next minute after 'after'
    # Set seconds and microseconds to 0
    current = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

    # Limit search to 5 years
    max_time = after.replace(year=after.year + 5)

    # Try to find a match
    while current < max_time:
        # Check if current matches
        if matches_cron(current, minute_set, hour_set, dom_set, month_set, dow_set):
            return current

        # Move to next minute
        current += datetime.timedelta(minutes=1)

        # Optimization: if we're at the end of a month, jump to next month
        # But this is complex, so we'll just increment minute by minute for now
        # For performance, we could add smarter jumps, but the problem says to raise ValueError if no match in 5 years

    raise ValueError("No matching time found within 5 years")
