def flatten(obj, sep="."):
    """
    Flatten a nested dictionary or list into a flat dictionary with path keys.

    Args:
        obj: The object to flatten (must be a dict at the top level)
        sep: The separator to use for joining path segments

    Returns:
        A flat dictionary with path keys

    Raises:
        TypeError: If the top-level object is not a dict
        ValueError: If any dict key contains the separator
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _flatten(current, path_parts):
        # If current is a dict
        if isinstance(current, dict):
            # Check that all keys are strings and don't contain separator
            for key in current:
                if not isinstance(key, str):
                    raise ValueError("All keys must be strings")
                if sep in key:
                    raise ValueError(f"Key '{key}' contains separator '{sep}'")

            # Process each key in order
            for key in current:
                new_path = path_parts + [key]
                value = current[key]

                # If value is a dict or list, recurse; otherwise add to result
                if isinstance(value, (dict, list)):
                    _flatten(value, new_path)
                else:
                    # Non-dict, non-list value is a leaf
                    result[sep.join(new_path)] = value

            # If the dict is empty, it's a leaf value
            if not current:
                result[sep.join(path_parts)] = {}

        # If current is a list
        elif isinstance(current, list):
            # Process each item in order
            for i, item in enumerate(current):
                new_path = path_parts + [str(i)]

                if isinstance(item, (dict, list)):
                    _flatten(item, new_path)
                else:
                    # Non-dict, non-list value is a leaf
                    result[sep.join(new_path)] = item

            # If the list is empty, it's a leaf value
            if not current:
                result[sep.join(path_parts)] = []

        # Any other value is a leaf
        else:
            result[sep.join(path_parts)] = current

    _flatten(obj, [])
    return result


def unflatten(flat, sep="."):
    """
    Unflatten a flat dictionary with path keys into a nested structure.

    Args:
        flat: A flat dictionary with path keys
        sep: The separator used in the path keys

    Returns:
        A nested dictionary/list structure

    Raises:
        ValueError: If the input is invalid (e.g., conflicting paths, invalid list indices)
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    # Check for empty input
    if not flat:
        return {}

    # Check that all keys are strings and don't contain separator issues
    for key in flat:
        if not isinstance(key, str):
            raise ValueError("All keys must be strings")

    # Build the nested structure
    result = {}

    # First, collect all paths and their values
    paths = []
    for key, value in flat.items():
        if key == "":
            raise ValueError("Empty key not allowed")
        parts = key.split(sep)
        paths.append((parts, value))

    # Sort paths by length to process shorter paths first
    paths.sort(key=lambda x: len(x[0]))

    # Process each path
    for parts, value in paths:
        current = result

        # Process each part except the last one
        for i, part in enumerate(parts[:-1]):
            next_part = parts[i + 1]

            # Check if current part is a list index
            is_next_list = _is_list_index(next_part)

            if part not in current:
                # Create new container based on what the next part expects
                if is_next_list:
                    current[part] = []
                else:
                    current[part] = {}
            elif is_next_list and not isinstance(current[part], list):
                # Conflict: expected list but found non-list
                raise ValueError(f"Conflict at path '{sep.join(parts[:i+1])}': expected list but found {type(current[part]).__name__}")
            elif not is_next_list and isinstance(current[part], list):
                # Conflict: expected dict but found list
                raise ValueError(f"Conflict at path '{sep.join(parts[:i+1])}': expected dict but found list")

            current = current[part]

        # Process the last part
        last_part = parts[-1]

        # Check if this is a list index
        if _is_list_index(last_part):
            # Ensure current is a list
            if not isinstance(current, list):
                raise ValueError(f"Conflict at path '{sep.join(parts)}': expected list but found {type(current).__name__}")

            # Convert to integer
            idx = int(last_part)

            # Check for leading zeros (except for "0" itself)
            if len(last_part) > 1 and last_part[0] == '0':
                raise ValueError(f"Invalid list index '{last_part}': leading zeros not allowed")

            # Extend list if needed
            if idx >= len(current):
                current.extend([None] * (idx - len(current) + 1))

            # Check if there's already a value at this position
            if current[idx] is not None:
                raise ValueError(f"Duplicate path '{sep.join(parts)}'")

            current[idx] = value
        else:
            # Ensure current is a dict
            if not isinstance(current, dict):
                raise ValueError(f"Conflict at path '{sep.join(parts)}': expected dict but found {type(current).__name__}")

            # Check for conflicts
            if last_part in current:
                raise ValueError(f"Duplicate path '{sep.join(parts)}'")

            current[last_part] = value

    # Validate lists are dense (0..n-1)
    def _validate_structure(obj):
        if isinstance(obj, list):
            # Check if list is dense
            for i, item in enumerate(obj):
                if item is None:
                    raise ValueError(f"List has gaps at index {i}")
            # Recursively validate items
            for item in obj:
                _validate_structure(item)
        elif isinstance(obj, dict):
            # Recursively validate values
            for value in obj.values():
                _validate_structure(value)

    _validate_structure(result)

    return result


def _is_list_index(s):
    """Check if a string is a valid list index (non-negative integer without leading zeros)."""
    if not s:
        return False
    # Check if all characters are digits
    if not s.isdigit():
        return False
    # Check for leading zeros (except for "0" itself)
    if len(s) > 1 and s[0] == '0':
        return False
    return True
