def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if env is None:
        env = {}

    # Tokenize the expression
    tokens = tokenize(expr)

    if not tokens:
        raise SyntaxError("Empty expression")

    # Parse and evaluate
    parser = Parser(tokens, env)
    result = parser.parse_expression(0)

    if parser.pos < len(parser.tokens):
        raise SyntaxError(f"Unexpected token: {parser.tokens[parser.pos]}")

    return result

def tokenize(expr: str):
    tokens = []
    i = 0
    while i < len(expr):
        # Skip whitespace
        if expr[i].isspace():
            i += 1
            continue

        # Check for operators and special characters
        if expr[i:i+2] in ('==', '!=', '<=', '>=', '&&', '||'):
            tokens.append(expr[i:i+2])
            i += 2
            continue

        if expr[i] in '()[]+-*/%!?<>,;':
            tokens.append(expr[i])
            i += 1
            continue

        # Check for identifiers
        if expr[i].isalpha() or expr[i] == '_':
            j = i
            while j < len(expr) and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(expr[i:j])
            i = j
            continue

        # Check for numbers (integers and floats)
        if expr[i].isdigit() or (expr[i] == '.' and i+1 < len(expr) and expr[i+1].isdigit()):
            j = i
            has_dot = False
            while j < len(expr) and (expr[j].isdigit() or (expr[j] == '.' and not has_dot)):
                if expr[j] == '.':
                    has_dot = True
                j += 1

            # Handle cases like "2." or ".5"
            if expr[j-1] == '.':
                j -= 1

            tokens.append(expr[i:j])
            i = j
            continue

        raise SyntaxError(f"Unexpected character: {expr[i]}")

    return tokens

class Parser:
    def __init__(self, tokens, env):
        self.tokens = tokens
        self.pos = 0
        self.env = env

    def current_token(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        self.pos += 1

    def parse_expression(self, min_precedence):
        # Parse the first term
        left = self.parse_unary()

        while True:
            token = self.current_token()
            if token is None:
                break

            # Get precedence of current operator
            prec = self.get_precedence(token)
            if prec < min_precedence:
                break

            # Check for conditional operator (ternary)
            if token == '?':
                self.advance()
                if self.current_token() is None:
                    raise SyntaxError("Expected expression after '?'")
                true_expr = self.parse_expression(0)
                if self.current_token() != ':':
                    raise SyntaxError("Expected ':' after true expression in conditional")
                self.advance()
                if self.current_token() is None:
                    raise SyntaxError("Expected expression after ':'")
                false_expr = self.parse_expression(0)

                # Short-circuit evaluation
                if left:
                    left = true_expr
                else:
                    left = false_expr
                continue

            # Check for logical operators
            if token in ('&&', '||'):
                self.advance()
                right = self.parse_unary()

                # Short-circuit evaluation
                if token == '&&':
                    left = 1 if left and right else 0
                else:  # ||
                    left = 1 if left or right else 0
                continue

            # Check for comparison operators
            if token in ('==', '!=', '<', '<=', '>', '>='):
                self.advance()
                right = self.parse_unary()

                if token == '==':
                    left = 1 if left == right else 0
                elif token == '!=':
                    left = 1 if left != right else 0
                elif token == '<':
                    left = 1 if left < right else 0
                elif token == '<=':
                    left = 1 if left <= right else 0
                elif token == '>':
                    left = 1 if left > right else 0
                elif token == '>=':
                    left = 1 if left >= right else 0

                # Check for chained comparisons (not allowed)
                next_token = self.current_token()
                if next_token in ('==', '!=', '<', '<=', '>', '>='):
                    raise SyntaxError("Chained comparisons are not allowed")
                continue

            # Check for arithmetic operators
            if token in ('+', '-'):
                self.advance()
                if token == '+':
                    left = left + self.parse_unary()
                else:
                    left = left - self.parse_unary()
                continue

            if token in ('*', '/', '%'):
                self.advance()
                right = self.parse_unary()

                if token == '*':
                    left = left * right
                elif token == '/':
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    # Check if result is integer
                    if isinstance(left, int) and isinstance(right, int) and left % right == 0:
                        left = left // right
                    else:
                        left = left / right
                elif token == '%':
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    # Python modulo semantics
                    left = left % right
                continue

            # Check for power operator
            if token == '^':
                self.advance()
                # Power is right-associative, so we need to parse the right side with higher precedence
                right = self.parse_expression(prec + 1)
                left = left ** right
                continue

            break

        return left

    def parse_unary(self):
        token = self.current_token()

        if token == '-':
            self.advance()
            return -self.parse_unary()

        if token == '+':
            self.advance()
            return self.parse_unary()

        if token == '!':
            self.advance()
            return 1 if not self.parse_unary() else 0

        return self.parse_primary()

    def parse_primary(self):
        token = self.current_token()

        if token is None:
            raise SyntaxError("Unexpected end of expression")

        # Handle parentheses
        if token == '(':
            self.advance()
            expr = self.parse_expression(0)
            if self.current_token() != ')':
                raise SyntaxError("Expected ')'")
            self.advance()
            return expr

        # Handle identifiers and function calls
        if isinstance(token, str) and (token[0].isalpha() or token[0] == '_'):
            self.advance()

            # Check if it's a function call
            if self.current_token() == '(':
                return self.handle_function_call(token)

            # It's a variable
            if token not in self.env:
                raise NameError(f"Undefined variable: {token}")
            return self.env[token]

        # Handle literals
        if isinstance(token, str) and (token.isdigit() or (token.count('.') == 1 and 
                (token[0].isdigit() or token[0] == '.') and 
                (token[-1].isdigit() or token[-1] == '.'))):
            self.advance()
            if '.' in token:
                return float(token)
            else:
                return int(token)

        # Handle lone operators that are errors
        if token in ('=', '&', '|'):
            raise SyntaxError(f"Lone operator: {token}")

        raise SyntaxError(f"Unexpected token: {token}")

    def handle_function_call(self, func_name):
        if self.current_token() != '(':
            raise SyntaxError("Expected '(' after function name")

        self.advance()  # consume '('

        args = []
        if self.current_token() != ')':
            args.append(self.parse_expression(0))
            while self.current_token() == ',':
                self.advance()
                args.append(self.parse_expression(0))

        if self.current_token() != ')':
            raise SyntaxError("Expected ')' in function call")
        self.advance()  # consume ')'

        # Check for known functions
        if func_name == 'abs':
            if len(args) != 1:
                raise SyntaxError("abs() requires exactly 1 argument")
            return abs(args[0])
        elif func_name == 'min':
            if len(args) < 1:
                raise SyntaxError("min() requires at least 1 argument")
            return min(args)
        elif func_name == 'max':
            if len(args) < 1:
                raise SyntaxError("max() requires at least 1 argument")
            return max(args)
        else:
            raise NameError(f"Undefined function: {func_name}")

    def get_precedence(self, token):
        if token == '?':
            return 1
        elif token == '||':
            return 2
        elif token == '&&':
            return 3
        elif token in ('==', '!=', '<', '<=', '>', '>='):
            return 4
        elif token in ('+', '-'):
            return 5
        elif token in ('*', '/', '%'):
            return 6
        elif token == '^':
            return 7
        else:
            return 0
