def load_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.splitlines()
    result = {}
    current_section = ""
    current_key = None
    current_value = None
    continuation_pending = False

    # First pass: parse the INI content
    for line_num, line in enumerate(lines, 1):
        # Skip empty lines
        if not line.strip():
            # End continuation if pending
            if continuation_pending:
                # Store the accumulated value
                if current_section not in result:
                    result[current_section] = {}
                result[current_section][current_key] = current_value.strip()
                continuation_pending = False
                current_key = None
                current_value = None
            continue

        # Check for continuation line (starts with whitespace and we have a pending entry)
        if continuation_pending and not line[0].isspace():
            # End continuation if pending
            if current_section not in result:
                result[current_section] = {}
            result[current_section][current_key] = current_value.strip()
            continuation_pending = False
            current_key = None
            current_value = None

        # Check for continuation line (starts with whitespace)
        if line[0].isspace() and continuation_pending:
            # Append to current value with newline
            current_value += "\n" + line.strip()
            continue

        # Skip comment lines (lines starting with # or ; after optional whitespace)
        stripped_line = line.lstrip()
        if stripped_line.startswith('#') or stripped_line.startswith(';'):
            continue

        # Check for section header
        if stripped_line.startswith('['):
            # Find closing bracket
            end_bracket = stripped_line.find(']')
            if end_bracket == -1:
                raise ValueError(f"line {line_num}: unclosed section header")

            section_name = stripped_line[1:end_bracket].strip()
            current_section = section_name
            # End any pending continuation
            if continuation_pending:
                if current_section not in result:
                    result[current_section] = {}
                result[current_section][current_key] = current_value.strip()
                continuation_pending = False
                current_key = None
                current_value = None
            continue

        # Check for key-value pair
        # Find first = or : separator
        eq_pos = stripped_line.find('=')
        colon_pos = stripped_line.find(':')

        # Determine separator position
        if eq_pos == -1 and colon_pos == -1:
            # No separator found - error
            raise ValueError(f"line {line_num}: missing separator")

        # Use the first separator found
        if eq_pos == -1:
            sep_pos = colon_pos
        elif colon_pos == -1:
            sep_pos = eq_pos
        else:
            sep_pos = min(eq_pos, colon_pos)

        # Extract key and value parts
        key_part = stripped_line[:sep_pos]
        value_part = stripped_line[sep_pos+1:]

        # Trim key and lowercase
        key = key_part.strip().lower()

        # Process value: handle comments and quotes
        # Find comment position (outside quotes)
        comment_pos = -1
        in_quotes = False
        i = 0
        while i < len(value_part):
            c = value_part[i]
            if c == '"' and (i == 0 or value_part[i-1] != '\\'):
                in_quotes = not in_quotes
            elif (c == ';' or c == '#') and not in_quotes:
                # Check if preceded by whitespace
                if i > 0 and value_part[i-1].isspace():
                    comment_pos = i
                    break
            i += 1

        # Extract value without inline comment
        if comment_pos != -1:
            value_part = value_part[:comment_pos]

        # Trim value
        value = value_part.strip()

        # Handle quoted values
        if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
            # Remove quotes and process escapes
            inner = value[1:-1]
            # Replace \" with "
            value = inner.replace('\\"', '"')
        elif value.startswith('"'):
