            raise ValueError(f"line {line_num}: unterminated quote")

        # Set up continuation if needed
        continuation_pending = True
        current_key = key
        current_value = value

        # If this is a new section, ensure it exists in result
        if current_section not in result:
            result[current_section] = {}

    # Handle final pending continuation
    if continuation_pending:
        if current_section not in result:
            result[current_section] = {}
        result[current_section][current_key] = current_value.strip()

    # Remove empty section if no keys
    if "" in result and len(result[""]) == 0:
        del result[""]

    # Second pass: interpolation
    # Create a copy for interpolation to avoid modifying during iteration
    interpolated = {}

    # Helper function to resolve a value with interpolation
    def resolve_value(section, key, visited=None):
        if visited is None:
            visited = set()

        # Check for cycle
        if (section, key) in visited:
            raise ValueError(f"cycle detected in interpolation for key '{key}' in section '{section}'")

        # Get the raw value
        if section not in result or key not in result[section]:
            raise ValueError(f"undefined reference: {key}")

        raw_value = result[section][key]

        # Mark as visited
        visited.add((section, key))

        # Process interpolation
        result_value = ""
        i = 0
        while i < len(raw_value):
            if i + 1 < len(raw_value) and raw_value[i:i+2] == '$$':
                # Literal $
                result_value += '$'
                i += 2
            elif i < len(raw_value) and raw_value[i] == '$':
                # Start of interpolation
                if i + 1 < len(raw_value) and raw_value[i+1] == '{':
                    # Find closing brace
                    j = i + 2
                    while j < len(raw_value) and raw_value[j] != '}':
                        j += 1

                    if j >= len(raw_value):
                        # Unclosed brace - this should be caught earlier, but handle gracefully
                        raise ValueError(f"line 0: unclosed interpolation")

                    ref = raw_value[i+2:j]

                    # Parse reference: ${key} or ${section:key}
                    if ':' in ref:
                        ref_parts = ref.split(':', 1)
                        ref_section = ref_parts[0].strip()
                        ref_key = ref_parts[1].strip().lower()
                    else:
                        ref_section = section
                        ref_key = ref.strip().lower()

                    # Resolve the reference
                    resolved = resolve_value(ref_section, ref_key, visited.copy())
                    result_value += resolved
                    i = j + 1
                else:
                    # Just a $ not followed by { - treat as literal
                    result_value += '$'
                    i += 1
            else:
                result_value += raw_value[i]
                i += 1

        return result_value

    # Apply interpolation to all values
    for section in result:
        interpolated[section] = {}
        for key in result[section]:
            try:
                interpolated[section][key] = resolve_value(section, key)
            except ValueError as e:
                if "cycle" not in str(e).lower():
                    raise ValueError(f"line 0: {e}")
                else:
                    raise

    return interpolated
