import re
from functools import total_ordering
from typing import List, Optional, Tuple, Union


@total_ordering
class Version:
    def __init__(self, version_str: str):
        self.original = version_str
        self._parse(version_str)

    def _parse(self, version_str: str):
        # Remove leading 'v' or '='
        s = version_str.strip()
        if s.startswith('v') or s.startswith('='):
            s = s[1:].strip()

        # Split build metadata
        build_meta = None
        if '+' in s:
            s, build_meta = s.split('+', 1)
            if not build_meta:
                raise ValueError("Invalid version: empty build metadata")

        # Split prerelease
        prerelease = None
        if '-' in s:
            s, prerelease = s.split('-', 1)
            if not prerelease:
                raise ValueError("Invalid version: empty prerelease")

        # Parse main version parts
        parts = s.split('.')
        if len(parts) < 1 or len(parts) > 3:
            raise ValueError("Invalid version: must have 1-3 version parts")

        # Validate and parse each part
        self.major = self._parse_numeric_part(parts[0], "major")
        self.minor = None
        self.patch = None

        if len(parts) >= 2:
            self.minor = self._parse_numeric_part(parts[1], "minor")
        if len(parts) >= 3:
            self.patch = self._parse_numeric_part(parts[2], "patch")

        # Parse prerelease identifiers
        self.prerelease = []
        if prerelease is not None:
            identifiers = prerelease.split('.')
            for ident in identifiers:
                if not ident:
                    raise ValueError("Invalid version: empty prerelease identifier")
                if not re.match(r'^[0-9A-Za-z-]+$', ident):
                    raise ValueError(f"Invalid version: invalid prerelease identifier '{ident}'")

                # Check if numeric
                if re.match(r'^[0-9]+$', ident):
                    # Check for leading zeros
                    if len(ident) > 1 and ident[0] == '0':
                        raise ValueError(f"Invalid version: leading zeros in numeric prerelease identifier '{ident}'")
                    self.prerelease.append(int(ident))
                else:
                    self.prerelease.append(ident)

        self.build = build_meta

    def _parse_numeric_part(self, part: str, name: str) -> int:
        if not part:
            raise ValueError(f"Invalid version: empty {name} part")
        if not re.match(r'^[0-9]+$', part):
            raise ValueError(f"Invalid version: {name} part '{part}' is not numeric")
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Invalid version: leading zeros in {name} part '{part}'")
        return int(part)

    def _compare_prerelease(self, other: 'Version') -> int:
        # No prerelease > has prerelease
        if not self.prerelease and other.prerelease:
            return 1
        if self.prerelease and not other.prerelease:
            return -1
        if not self.prerelease and not other.prerelease:
            return 0

        # Compare identifier by identifier
        for i in range(min(len(self.prerelease), len(other.prerelease))):
            a = self.prerelease[i]
            b = other.prerelease[i]

            # Both numeric
            if isinstance(a, int) and isinstance(b, int):
                if a < b:
                    return -1
                elif a > b:
                    return 1
            # Numeric < alphanumeric
            elif isinstance(a, int) and isinstance(b, str):
                return -1
            elif isinstance(a, str) and isinstance(b, int):
                return 1
            # Both alphanumeric: ASCII order
            else:
                if a < b:
                    return -1
                elif a > b:
                    return 1

        # Shorter list is smaller
        if len(self.prerelease) < len(other.prerelease):
            return -1
        elif len(self.prerelease) > len(other.prerelease):
            return 1

        return 0

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return False
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self.prerelease == other.prerelease)

    def __lt__(self, other: 'Version') -> bool:
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch
        return self._compare_prerelease(other) < 0

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, tuple(self.prerelease)))

    def __repr__(self):
        return f"Version({self.original!r})"


def parse(v: str) -> Version:
    return Version(v)


def _is_partial_version(version_str: str) -> bool:
    """Check if version string is partial (e.g., '1', '1.x', '1.2.*', 'X')"""
    version_str = version_str.strip()
    if version_str == '*':
        return True
    if version_str == 'X':
        return True
    if version_str.endswith('.x') or version_str.endswith('.X'):
        return True
    if version_str.endswith('.*'):
        return True
    # Check if it's just a major version number
    parts = version_str.split('.')
    if len(parts) == 1 and re.match(r'^[0-9]+$', parts[0]):
        return True
    return False


def _parse_partial_version(version_str: str) -> Tuple[int, Optional[int], Optional[int]]:
    """Parse a partial version string to (major, minor, patch)"""
    version_str = version_str.strip()

    if version_str == '*':
        return (0, 0, 0)
    if version_str == 'X':
        return (0, 0, 0)

    # Replace X/x with 0
    version_str = re.sub(r'\.x$', '.0', version_str, flags=re.IGNORECASE)
    version_str = re.sub(r'\.\*$', '.0', version_str)

    parts = version_str.split('.')
    major = int(parts[0])
    minor = int(parts[1]) if len(parts) > 1 else None
    patch = int(parts[2]) if len(parts) > 2 else None

    return (major, minor, patch)


def _version_from_partial(major: int, minor: Optional[int], patch: Optional[int], 
                          fill_zeros: bool = True) -> Version:
    """Create a Version object from partial components"""
    if minor is None:
        minor = 0 if fill_zeros else None
    if patch is None:
        patch = 0 if fill_zeros else None

    # Create version string
    version_str = str(major)
    if minor is not None:
        version_str += f".{minor}"
    if patch is not None:
        version_str += f".{patch}"

    return parse(version_str)


def _get_upper_bound(version: Version, is_partial: bool, is_x_range: bool) -> Tuple[int, Optional[int], Optional[int]]:
    """Get the upper bound version components for X-ranges"""
    major = version.major
    minor = version.minor
    patch = version.patch

    if is_x_range:
        # ^0.x means <1.0.0
        if major == 0 and minor is None:
            return (1, None, None)
        # ^0.0.x means <0.1.0
        elif major == 0 and minor == 0 and patch is None:
            return (0, 1, None)
        # ^0.2.3 means <0.3.0
        elif major == 0 and minor is not None and patch is not None:
            return (0, minor + 1, None)
        # ^1.2.3 means <2.0.0
        elif major != 0:
            return (major + 1, None, None)
    else:
        # X-ranges with .x or .*
        if minor is None:
            return (major + 1, None, None)
        elif patch is None:
            return (major, minor + 1, None)

    # For full versions, upper bound is next patch
    if patch is not None:
        return (major, minor, patch + 1)
    elif minor is not None:
        return (major, minor + 1, None)
    else:
        return (major + 1, None, None)


def _get_lower_bound(version: Version, is_partial: bool, is_x_range: bool) -> Tuple[int, Optional[int], Optional[int]]:
    """Get the lower bound version components for X-ranges"""
    major = version.major
    minor = version.minor
    patch = version.patch

    if is_x_range:
        # ^0.x means >=0.0.0
        if major == 0 and minor is None:
            return (0, 0, 0)
        # ^0.0.x means >=0.0.0
        elif major == 0 and minor == 0 and patch is None:
            return (0, 0, 0)
        # ^0.2.3 means >=0.2.3
        elif major == 0 and minor is not None and patch is not None:
            return (major, minor, patch)
        # ^1.2.3 means >=1.2.3
        elif major != 0:
            return (major, minor or 0, patch or 0)
    else:
        # X-ranges with .x or .*
        if minor is None:
            return (major, 0, 0)
        elif patch is None:
            return (major, minor, 0)

    # For full versions, lower bound is the version itself
    return (major, minor, patch)


def _parse_comparator(range_str: str) -> Tuple[str, Version, bool, bool]:
    """Parse a comparator string into (operator, version, is_partial, is_x_range)"""
    range_str = range_str.strip()

    # Extract operator
    op = ''
    if range_str.startswith('>='):
        op = '>='
        range_str = range_str[2:].strip()
    elif range_str.startswith('<='):
        op = '<='
        range_str = range_str[2:].strip()
    elif range_str.startswith('>'):
        op = '>'
        range_str = range_str[1:].strip()
    elif range_str.startswith('<'):
        op = '<'
        range_str = range_str[1:].strip()
    elif range_str.startswith('='):
        op = '='
        range_str = range_str[1:].strip()
    else:
        op = '='

    # Check for partial version
    is_partial = _is_partial_version(range_str)
    is_x_range = range_str.strip() == '*' or range_str.strip() == 'X' or '.x' in range_str.lower() or '.*' in range_str

    # Parse version
    version = parse(range_str)

    return (op, version, is_partial, is_x_range)


def _satisfies_single_comparator(version: Version, op: str, comp_version: Version, 
                                 is_partial: bool, is_x_range: bool) -> bool:
    """Check if version satisfies a single comparator"""
    # Handle partial versions
    if is_partial:
        # Normalize version for comparison
        major, minor, patch = _get_lower_bound(comp_version, is_partial, is_x_range)
        lower_bound = _version_from_partial(major, minor, patch)

        major_upper, minor_upper, patch_upper = _get_upper_bound(comp_version, is_partial, is_x_range)
        upper_bound = _version_from_partial(major_upper, minor_upper, patch_upper, fill_zeros=False)

        # For partial versions, we need to handle the comparison carefully
        if op == '>=':
            # >=1.2 means >=1.2.0
            return version >= lower_bound
        elif op == '<':
            # <1.2 means <1.2.0
            return version < lower_bound
        elif op == '<=':
            # <=1.2 means <1.3.0
            return version < upper_bound
        elif op == '>':
            # >1.2 means >=1.3.0
            return version >= upper_bound
        elif op == '=':
            # =1.2 means >=1.2.0 <1.3.0
            return version >= lower_bound and version < upper_bound
    else:
        # Full version comparison
        if op == '>=':
            return version >= comp_version
        elif op == '<':
            return version < comp_version
        elif op == '<=':
            return version <= comp_version
        elif op == '>':
            return version > comp_version
        elif op == '=':
            return version == comp_version

    return False


def _parse_range_set(range_str: str) -> List[Tuple[str, Version, bool, bool]]:
    """Parse a single comparator set (whitespace-separated comparators)"""
    parts = range_str.split()
    if not parts:
        return []  # Empty set matches everything

    comparators = []
    for part in parts:
        if part == '*':
            # * matches everything, so this set matches everything
            return []  # Special case: empty set means match all
        comparators.append(_parse_comparator(part))

    return comparators


def _satisfies_range_set(version: Version, comparators: List[Tuple[str, Version, bool, bool]]) -> bool:
    """Check if version satisfies all comparators in a set"""
    # Empty set matches everything
    if not comparators:
        return True

    # Check if version is prerelease
    is_prerelease = len(version.prerelease) > 0

    # For prerelease versions, we need special handling
    if is_prerelease:
        # A prerelease version only satisfies a set if some comparator has a prerelease
        # with the same MAJOR.MINOR.PATCH and a prerelease
        has_matching_prerelease = False
        for _, comp_version, _, _ in comparators:
            if (comp_version.major == version.major and
                comp_version.minor == version.minor and
                comp_version.patch == version.patch and
                len(comp_version.prerelease) > 0):
                has_matching_prerelease = True
                break

        if not has_matching_prerelease:
            return False

    # Check all comparators
    for op, comp_version, is_partial, is_x_range in comparators:
        if not _satisfies_single_comparator(version, op, comp_version, is_partial, is_x_range):
            return False

    return True


def satisfies(version: str, rng: str) -> bool:
    version_obj = parse(version)

    # Split into sets by ||
    sets = rng.split('||')

    for set_str in sets:
        set_str = set_str.strip()
        if not set_str:
            continue

        comparators = _parse_range_set(set_str)
        if _satisfies_range_set(version_obj, comparators):
            return True

    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    if not versions:
        return None

    # Parse all versions
    parsed_versions = [(parse(v), v) for v in versions]

    # Filter to satisfying versions
    satisfying = [(v, orig) for v, orig in parsed_versions if satisfies(orig, rng)]

    if not satisfying:
        return None

    # Return the maximum satisfying version (original string)
    return max(satisfying, key=lambda x: x[0])[1]
