            try:
                result[key] = _load_value(value_type, value, f"{path}[{key}]")
            except LoadError as e:
                raise LoadError(f"{path}[{key}]", str(e).split(": ", 1)[1])
        return result

    # Handle tuple[T, ...] (variable-length tuple)
    if origin is tuple:
        if not isinstance(data, list):
            raise LoadError(path, f"expected list for tuple, got {type(data).__name__}")
        if not args:
            return tuple(data)  # No type info, return as-is

        # Check if it's a fixed-length tuple (e.g., tuple[int, str, bool])
        if Ellipsis in args:
            # Variable-length tuple: tuple[T, ...]
            item_type = args[0]
            result = []
            for i, item in enumerate(data):
                try:
                    result.append(_load_value(item_type, item, f"{path}[{i}]"))
                except LoadError as e:
                    raise LoadError(f"{path}[{i}]", str(e).split(": ", 1)[1])
            return tuple(result)
        else:
            # Fixed-length tuple: tuple[A, B, C]
            if len(data) != len(args):
                raise LoadError(path, f"expected tuple of length {len(args)}, got length {len(data)}")
            result = []
            for i, (item, item_type) in enumerate(zip(data, args)):
                try:
                    result.append(_load_value(item_type, item, f"{path}[{i}]"))
                except LoadError as e:
                    raise LoadError(f"{path}[{i}]", str(e).split(": ", 1)[1])
            return tuple(result)

    # Handle primitive types
    # bool must not be accepted for int or float
    if type_hint is bool:
        if not isinstance(data, bool):
            raise LoadError(path, f"expected bool, got {type(data).__name__}")
        return data

    if type_hint is int:
        if isinstance(data, bool) or not isinstance(data, int):
            raise LoadError(path, f"expected int, got {type(data).__name__}")
        return data

    if type_hint is float:
        if isinstance(data, bool):
            raise LoadError(path, f"expected float, got bool")
        if isinstance(data, int):
            return float(data)
        if not isinstance(data, float):
            raise LoadError(path, f"expected float, got {type(data).__name__}")
        return data

    if type_hint is str:
        if not isinstance(data, str):
            raise LoadError(path, f"expected str, got {type(data).__name__}")
        return data

    # If we get here, it's an unsupported type
    raise LoadError(path, f"unsupported type: {type_hint}")
