#!/bin/bash

# Parse options
DELIM=","
SUMMARY=0

while getopts ":d:s" opt; do
    case $opt in
        d)
            DELIM="$OPTARG"
            ;;
        s)
            SUMMARY=1
            ;;
        \?)
            echo "Invalid option: -$OPTARG" >&2
            exit 1
            ;;
        :)
            echo "Option -$OPTARG requires an argument." >&2
            exit 1
            ;;
    esac
done

shift $((OPTIND - 1))

COLUMN="$1"
FILE="$2"

# Validate column specification
if [[ -z "$COLUMN" ]]; then
    echo "Usage: $0 [-d DELIM] [-s] COLUMN [FILE]" >&2
    exit 1
fi

# Check if column is numeric index
if [[ "$COLUMN" =~ ^#([0-9]+)$ ]]; then
    COL_IDX="${BASH_REMATCH[1]}"
    IS_INDEX=1
else
    IS_INDEX=0
fi

# Read file or stdin
if [[ -n "$FILE" ]]; then
    if [[ ! -f "$FILE" ]]; then
        echo "File not found: $FILE" >&2
        exit 1
    fi
    INPUT="$FILE"
else
    INPUT="/dev/stdin"
fi

# Process CSV with awk
awk -v delim="$DELIM" -v col_spec="$COLUMN" -v is_index="$IS_INDEX" -v summary="$SUMMARY" '
BEGIN {
    # Initialize variables
    col_idx = 0
    header_found = 0
    field_count = 0
    line_num = 0
    in_quote = 0
    current_field = ""
    fields_count = 0
    fields = ""
    numeric_count = 0
    sum_val = 0
    min_val = ""
    max_val = ""
}

# Function to handle end of field
function end_field() {
    if (in_quote) {
        # Still in quoted field, append to current field
        current_field = current_field delim
    } else {
        # End of field
        fields[++fields_count] = current_field
        current_field = ""
    }
}

# Function to handle end of record
function end_record() {
    # Handle last field if not empty
    if (current_field != "" || in_quote) {
        fields[++fields_count] = current_field
        current_field = ""
    }

    # If we have a header row, find the column index
    if (!header_found) {
        header_found = 1
        # Find column index
        if (is_index) {
            col_idx = col_spec
        } else {
            for (i = 1; i <= fields_count; i++) {
                if (fields[i] == col_spec) {
                    col_idx = i
                    break
                }
            }
        }

        # Check if column was found
        if (col_idx == 0) {
            print "Error: Column \"" col_spec "\" not found" > "/dev/stderr"
            exit 3
        }

        # If summary mode, skip header row
        if (summary) {
            fields_count = 0
            return
        }
    }

    # Check if we have enough fields
    if (fields_count < col_idx) {
        # Treat missing fields as empty
        for (i = fields_count + 1; i <= col_idx; i++) {
            fields[i] = ""
        }
        fields_count = col_idx
    }

    # Get the target field
    val = fields[col_idx]

    # Process the value
    if (summary) {
        # Check if numeric (integer or decimal with optional sign)
        if (val ~ /^[-+]?([0-9]+\.?[0-9]*|\.[0-9]+)$/) {
            num_val = val + 0
            numeric_count++
            sum_val += num_val
            if (min_val == "" || num_val < min_val) min_val = num_val
            if (max_val == "" || num_val > max_val) max_val = num_val
        }
    } else {
        # Print the value, replacing internal newlines with literal \n
        gsub(/\n/, "\\n", val)
        print val
    }

    # Reset for next record
    fields_count = 0
    delete fields
}

# Main processing
{
    # Read line and normalize line endings
    line = $0
    gsub(/\r\n/, "\n", line)
    gsub(/\r/, "\n", line)

    # Process character by character
    n = length(line)
    for (i = 1; i <= n; i++) {
        c = substr(line, i, 1)

        if (in_quote) {
            if (c == "\"") {
                # Check for escaped quote
                if (i < n && substr(line, i+1, 1) == "\"") {
                    current_field = current_field "\""
                    i++  # Skip next quote
                } else {
                    # End of quoted field
                    in_quote = 0
                }
            } else {
                current_field = current_field c
            }
        } else {
            if (c == delim) {
                end_field()
            } else if (c == "\"") {
                in_quote = 1
            } else {
                current_field = current_field c
            }
        }
    }

    # Handle end of line
    if (in_quote) {
        # Still in quoted field, add newline to current field
        current_field = current_field "\n"
    } else {
        end_field()
        end_record()
    }
}

END {
    # Check for unterminated quote
    if (in_quote) {
        print "Error: Unterminated quote at end of input" > "/dev/stderr"
        exit 4
    }

    # Handle last record if not processed
    if (fields_count > 0 || current_field != "") {
        end_record()
    }

    # Print summary if requested
    if (summary) {
        if (numeric_count == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", numeric_count, sum_val, min_val, max_val
        }
    }
}
' "$INPUT"
