    else if (substr(value_part, 1, 1) == "\"") {
        # Double quoted value
        i = 2
        while (i <= len) {
            c = substr(value_part, i, 1)
            if (c == "\\") {
                # Escape sequence
                next_c = substr(value_part, i+1, 1)
                if (next_c == "n") {
