        # Find unquoted # (space followed by #)
        # We need to be careful: a#b should keep the hash
        # Only space followed by # starts a comment
        j = 1
        while (j <= len) {
            c = substr(value_part, j, 1)
            if (c == " " || c == "\t") {
                # Check if next char is #
                if (substr(value_part, j+1, 1) == "#") {
