                    break
                }
            }
            value = value c
            j++
        }
        # Trim trailing spaces and tabs
        gsub(/[[:space:]]+$/, "", value)
    }

    # Store key-value pair (later values override earlier ones)
    keys[key] = value
    # Track order of first occurrence
    if (!(key in seen)) {
        order[++order_count] = key
        seen[key] = 1
    }
}

END {
    if (invalid) exit 1

    # Output in order of last occurrence (which is same as order since we only add once)
    for (i = 1; i <= order_count; i++) {
        key = order[i]
        value = keys[key]

        # Escape single quotes for shell: ' -> '\'' 
        # Replace each ' with '\'' 
        gsub(/'\''/, "'\''\\'\'''\''", value)

        # Output: export KEY='value'
        print "export " key "='\''" value "'\''"
    }
}
' "$FILE" 2>&1)

