#!/bin/bash

# Default values
N=10
CASE_INSENSITIVE=0

# Parse options
while [[ $# -gt 0 ]]; do
    case "$1" in
        -n)
            if [[ $# -lt 2 ]]; then
                echo "Usage: $0 [-n N] [-i]" >&2
                exit 2
            fi
            N="$2"
            shift 2
            ;;
        -i)
            CASE_INSENSITIVE=1
            shift
            ;;
        *)
            echo "Usage: $0 [-n N] [-i]" >&2
            exit 2
            ;;
    esac
done

# Validate N
if ! [[ "$N" =~ ^[0-9]+$ ]] || [[ "$N" -le 0 ]]; then
    echo "Usage: $0 [-n N] [-i]" >&2
    exit 2
fi

# Process input
if [[ "$CASE_INSENSITIVE" -eq 1 ]]; then
    awk '
    BEGIN {
        IGNORECASE = 0  # We handle case-insensitivity manually
    }
    {
        # Convert to lowercase if case-insensitive
        if (IGNORECASE) {
            $0 = tolower($0)
        }
        # Replace non-word characters (letters, digits, apostrophes) with spaces
        gsub(/[^[:alnum:]'"'"']/, " ")
        # Split into words
        n = split($0, words, " ")
        for (i = 1; i <= n; i++) {
            word = words[i]
            # Skip empty words
            if (word == "") continue
            # Strip leading apostrophes
            while (substr(word, 1, 1) == "'"'"'") {
                word = substr(word, 2)
            }
            # Strip trailing apostrophes
            while (substr(word, length(word), 1) == "'"'"'") {
                word = substr(word, 1, length(word) - 1)
            }
            # Skip if word is empty after stripping apostrophes
            if (word == "") continue
            # Count the word
            count[word]++
        }
    }
    END {
        for (word in count) {
            print count[word], word
        }
    }
    ' | sort -t' ' -k1,1nr -k2,2 | head -n "$N"
else
    awk '
    {
        # Replace non-word characters (letters, digits, apostrophes) with spaces
        gsub(/[^[:alnum:]'"'"']/, " ")
        # Split into words
        n = split($0, words, " ")
        for (i = 1; i <= n; i++) {
            word = words[i]
            # Skip empty words
            if (word == "") continue
            # Strip leading apostrophes
            while (substr(word, 1, 1) == "'"'"'") {
                word = substr(word, 2)
            }
            # Strip trailing apostrophes
            while (substr(word, length(word), 1) == "'"'"'") {
                word = substr(word, 1, length(word) - 1)
            }
            # Skip if word is empty after stripping apostrophes
            if (word == "") continue
            # Count the word
            count[word]++
        }
    }
    END {
        for (word in count) {
            print count[word], word
        }
    }
    ' | LC_ALL=C sort -t' ' -k1,1nr -k2,2 | head -n "$N"
fi
